   PROMPT","      }]","    }","  ]","","  ai_text = ask_ai(messages)","  content_type :json","  { message: ai_text }.to_json","end"],"id":4}],[{"start":{"row":46,"column":0},"end":{"row":98,"column":3},"action":"remove","lines":["def ask_ai(messages)","  # 接続先・アクセスキー・モデルは、セットアップが用意した環境変数を使う（.env に鍵を書かない）","  url = ENV['ANTHROPIC_BASE_URL']","  key = ENV['ANTHROPIC_AUTH_TOKEN']","  # サービス用のモデル（セットアップが設定する。軽くて速い Haiku。Claude Code 本体の Sonnet とは別）","  model = ENV['AI_GATEWAY_MODEL']","","  # AI Gateway への通信を準備する（JSON でやり取りする）","  conn = Faraday.new(url: url) do |f|","    f.request :json","    f.response :json","    f.adapter Faraday.default_adapter","  end","","  # AI Gateway にメッセージを送信する","  response = conn.post('v1/chat/completions') do |req|","    req.headers['Authorization'] = \"Bearer #{key}\"","    # ネット検索が入ると時間がかかることがあるので、タイムアウトを長めにする","    req.options.timeout = 60","    req.body = {","      model: model,","      messages: messages,","      inferenceConfig: { maxTokens: 1024 },","      # AI が必要と判断したら、ネットで最新情報を検索する（検索はゲートウェイが実行）","      toolConfig: {","        tools: [","          {","            toolSpec: {","              name: 'web_search',","              description: 'Search the web for current, up-to-date information.',","              inputSchema: {","                json: {","                  type: 'object',","                  properties: { query: { type: 'string' } },","                  required: ['query']","                }","              }","            }","          }","        ],","        toolChoice: { auto: {} }","      }","    }","  end","","  # 通信が成功したら AI の回答テキストだけを取り出して返す","  if response.status == 200","    data = response.body","    data.dig('output', 'message', 'content', 0, 'text')","  else","    \"エラーが発生しました（#{response.status}）\"","  end","end"],"id":4},{"start":{"row":46,"column":0},"end":{"row":85,"column":3},"action":"insert","lines":["def ask_ai(messages)","  key = ENV['GEMINI_API_KEY']","  return 'GEMINI_API_KEYが設定されていません' if key.ni