      tasks_data = JSON.parse(res_text)","        tasks_data.each do |t|","          next if t['name'].nil? || t['name'].empty?","          # 今回作った親タスクの下に小タスクとして登録","          current_user.tasks.create(","            name: t['name'],","            description: t['description'] || '',","            due_date: task.due_date,","            parent_task_id: task.id","          )","        end","      rescue JSON::ParserError => e","        puts \"JSON解析エラー: #{e.message}\"","      end","    end","  end","","  redirect '/mypage'","end"]}],[{"start":{"row":202,"column":0},"end":{"row":273,"column":3},"action":"remove","lines":["post '/tasks' do","  require_login","","  # 1. 入力された情報で「親タスク」を作成","  task = current_user.tasks.create(","    name: params[:name],","    description: params[:description],","    due_date: params[:due_date].present? ? params[:due_date] : nil,","    color: params[:color] || 'sky'","  )","","  file = params[:file]","","  # 2. 写真が添えられている場合のみ、AIで解析して「小タスク」を追加","  if file && file[:tempfile] && task.persisted?","    base64_data = Base64.strict_encode64(file[:tempfile].read)","    mime_type = file[:type]","    key = ENV['GEMINI_API_KEY']","","    conn = Faraday.new(url: 'https://generativelanguage.googleapis.com') do |f|","      f.request :json","      f.response :json","      f.adapter Faraday.default_adapter","    end","","    prompt = <<~PROMPT","      画像の向きを補正して目次を読み取ってください。","      単元名やSection名を抽出し、必ず以下のJSON配列形式のみで返してください。","      [","        {\"name\": \"Part 1 Section 1 形容詞句\", \"description\": \"p.16〜\"},","        {\"name\": \"Part 1 Section 2 動詞句\", \"description\": \"p.20〜\"}","      ]","    PROMPT","","    payload = {","      contents: [{","        parts: [","          { inline_data: { mime_type: mime_type, data: base64_data } },","          { text: prompt }","        ]","      }],","      generationConfig: { response_mime_type: \"application/json\" }","    }","","    # 最新モデル gemini-2.0-flash を使用","    response = conn.post(\"/v1beta/models/gemini-2