 << { text: prompt }","","      payload = {","        contents: [{ parts: parts }],","        generationConfig: { response_mime_type: \"application/json\" }","      }","","      key = ENV['GEMINI_API_KEY']","      conn = Faraday.new(url: 'https://generativelanguage.googleapis.com') do |f|","        f.request :json","        f.response :json","        f.adapter Faraday.default_adapter","      end","","      response = conn.post(\"/v1beta/models/gemini-2.0-flash:generateContent?key=#{key.strip}\") do |req|","        req.headers['Content-Type'] = 'application/json'","        req.body = payload","      end","","      if response.status == 200","        res_text = response.body.dig('candidates', 0, 'content', 'parts', 0, 'text').to_s","        begin","          tasks_data = JSON.parse(res_text)","          tasks_data.each do |t|","            next if t['name'].nil? || t['name'].empty?","            current_user.tasks.create(","              name: t['name'],","              description: t['description'] || '',","              due_date: task.due_date,","              parent_task_id: task.id","            )","          end","        rescue JSON::ParserError => e","          puts \"JSON解析エラー: #{e.message}\"","        end","      end","    end","  end","","  redirect '/mypage'","end"]}],[{"start":{"row":11,"column":0},"end":{"row":19,"column":11},"action":"insert","lines":["# 👇 ここから追加","configure do","  begin","    ActiveRecord::MigrationContext.new('db/migrate', ActiveRecord::SchemaMigration).migrate","  rescue => e","    puts \"マイグレーション実行エラー: #{e.message}\"","  end","end","# 👆 ここまで追加"],"id":66}]]},"ace":{"folds":[],"scrolltop":0,"scrollleft":0,"selection":{"start":{"row":19,"column":11},"end":{"row":19,"column":11},"isBackwards":false},"options":{"guessTabSize":true,"useWrapMode":false,"wrapToView":true},"firstLineState":0},"timestamp":1787762653269,"hash":"0b49763a491f363d4c4427bfe7861f1664a1972a"}